#include <stdio.h>
#include <stdlib.h>
#include <time.h>

/* 摊还分析实验: 栈 MULTIPOP —— n 次混合操作的总代价 <= 2n, 平摊 O(1)
 * 每个元素至多被压入 1 次、弹出 1 次, 故总代价 <= 2n 恒成立 */
#define MAXN 100000
int st[MAXN];

int main(void) {
    int n, top = 0;
    long long total = 0;
    srand((unsigned)time(NULL));
    printf("输入操作次数 n (<= 100000): ");
    if (scanf("%d", &n) != 1 || n <= 0 || n > MAXN) { printf("输入无效!\n"); return 1; }
    for (int i = 0; i < n; i++) {
        int op = rand() % 3;               /* 0=PUSH 1=POP 2=MULTIPOP */
        if (op == 0) { st[top++] = i; total += 1; }   /* PUSH 代价 1 */
        else if (op == 1) {
            if (top > 0) top--;
            total += 1;                    /* POP 代价 1(空栈也计 1) */
        } else {
            int k = rand() % 10 + 1;       /* MULTIPOP(k): 弹出 min(k, top) */
            int c = k < top ? k : top;
            top -= c;
            total += c;                    /* 实际代价 = 弹出个数 */
        }
    }
    printf("操作次数 n = %d, 总代价 = %lld, 平均 = %.2f\n", n, total, (double)total / n);
    printf("上界 2n = %d, 总代价 <= 2n: %s\n", 2 * n, total <= 2LL * n ? "是" : "否");
    return 0;
}

#include <stdio.h>
#include <string.h>
#include <stdlib.h>

/* 记账法演示: 栈操作序列
 * PUSH 记账 2(1 元付压栈, 1 元存入该元素作信用), POP/MULTIPOP 记账 0
 * 不变式: 信用余额 = 栈中元素个数 >= 0, 故总记账 >= 总实际代价 */
int st[1000];

int main(void) {
    char line[4096], *tok;
    int top = 0, credit = 0, k;
    long long real_total = 0, acct_total = 0;
    printf("输入操作序列(如: P P P m3 p P): ");
    if (!fgets(line, sizeof(line), stdin)) return 1;
    tok = strtok(line, " \n");
    while (tok) {
        if (tok[0] == 'P') {                 /* PUSH: 实际 1, 记账 2 */
            st[top++] = 1;                   /* 1 表示该元素带 1 元信用 */
            real_total += 1; acct_total += 2; credit += 1;
            printf("PUSH   实际 1  记账 2  信用余额 %d\n", credit);
        } else if (tok[0] == 'p') {          /* POP: 实际 1, 记账 0 */
            if (top == 0) { printf("空栈! 忽略该操作\n"); }
            else { top--; real_total += 1; credit -= 1;
                   printf("POP    实际 1  记账 0  信用余额 %d\n", credit); }
        } else if (tok[0] == 'm') {          /* MULTIPOP(k): 实际 min(k,top), 记账 0 */
            k = atoi(tok + 1);
            int c = k < top ? k : top;
            top -= c; credit -= c; real_total += c;
            printf("MULTIPOP(%d) 实际 %d  记账 0  信用余额 %d\n", k, c, credit);
        }
        tok = strtok(NULL, " \n");
    }
    printf("总实际代价 %lld, 总记账 %lld, 信用余额 %d (恒非负? %s)\n",
           real_total, acct_total, credit, credit >= 0 ? "是" : "否");
    return 0;
}

#include <stdio.h>
#include <string.h>
#include <stdlib.h>

/* 势能法演示: 栈, 势函数 Φ = 栈中元素个数
 * 平摊代价 ĉ = c + ΔΦ: PUSH=2, POP=0, MULTIPOP(k)=0
 * 恒等式: Σĉ = Σc + Φ终 - Φ初 */
int st[1000];

int main(void) {
    char line[4096], *tok;
    int top = 0, k;
    long long sum_c = 0, sum_ac = 0;
    printf("输入操作序列(如: P P P m3 p P): ");
    if (!fgets(line, sizeof(line), stdin)) return 1;
    tok = strtok(line, " \n");
    while (tok) {
        int c = 0, phi_before = top, phi_after = top;
        if (tok[0] == 'P') { st[top++] = 1; c = 1; phi_after = top; }
        else if (tok[0] == 'p') {
            if (top == 0) { printf("空栈! 忽略\n"); tok = strtok(NULL, " \n"); continue; }
            top--; c = 1; phi_after = top;
        } else if (tok[0] == 'm') {
            k = atoi(tok + 1);
            int cnt = k < top ? k : top;
            top -= cnt; c = cnt; phi_after = top;
        }
        int ac = c + (phi_after - phi_before);   /* 平摊代价 = 实际 + ΔΦ */
        sum_c += c; sum_ac += ac;
        printf("操作 %-10s 实际 %2d  Φ: %d->%d  ΔΦ %3d  平摊 %2d\n",
               tok, c, phi_before, phi_after, phi_after - phi_before, ac);
        tok = strtok(NULL, " \n");
    }
    printf("Σ实际 = %lld, Σ平摊 = %lld, Φ终 - Φ初 = %d\n", sum_c, sum_ac, top);
    printf("验证 Σ平摊 = Σ实际 + Φ终 - Φ初: %s\n",
           sum_ac == sum_c + top ? "是" : "否");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* 动态表: 满时翻倍扩张, 负载因子降到 1/4 时收缩一半 —— 平摊 O(1)
 * 阈值取 1/4 而非 1/2, 避免边界反复 insert/delete 的抖动(thrashing) */
int main(void) {
    char line[4096], *tok;
    int *tab = NULL, num = 0, size = 0;
    long long copies = 0;
    printf("输入操作序列(如: I I I I I D D D): ");
    if (!fgets(line, sizeof(line), stdin)) return 1;
    tok = strtok(line, " \n");
    while (tok) {
        if (tok[0] == 'I') {
            if (num == size) {               /* 扩张: 容量翻倍并复制 */
                int ns = size == 0 ? 1 : size * 2;
                int *nt = (int *)malloc(ns * sizeof(int));
                for (int i = 0; i < num; i++) nt[i] = tab[i];
                free(tab); tab = nt;
                copies += num;
                size = ns;
                printf("扩张 %d -> %d (复制 %d)\n", size / 2, size, num);
            }
            tab[num++] = num;
            printf("INSERT: num=%d size=%d 负载=%.2f\n", num, size, (double)num / size);
        } else if (tok[0] == 'D') {
            if (num == 0) { printf("空表! 忽略\n"); }
            else {
                num--;
                if (size > 1 && num <= size / 4) {   /* 收缩: 负载降到 1/4 */
                    int ns = size / 2;
                    int *nt = (int *)malloc(ns * sizeof(int));
                    for (int i = 0; i < num; i++) nt[i] = tab[i];
                    free(tab); tab = nt;
                    copies += num;
                    size = ns;
                    printf("收缩 %d -> %d (复制 %d)\n", size * 2, size, num);
                }
                printf("DELETE: num=%d size=%d 负载=%.2f\n", num, size, (double)num / size);
            }
        }
        tok = strtok(NULL, " \n");
    }
    free(tab);
    printf("总复制次数 = %lld (平摊到每次操作 O(1))\n", copies);
    return 0;
}
